window.MONSTER_CHUNK_34 = [{"name":"Degenerate Serpentfolk","cr":4,"xp":1200,"alignment":"NE","size":"Medium","type":"monstrous humanoid","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":18,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+1 Dex, +7 natural","hp":47,"hd":"5d10+20","hdvalue":5,"fort":7,"ref":5,"will":2,"immunities":["mind-affecting effects","paralysis","poison"],"sr":15,"speed":[{"type":"land","speed":30}],"melee":"dagger +10 (1d4+5/19-20), bite +6 (1d6+2 plus poison)","space":"5 ft.","reach":"5 ft.","strength":20,"dexterity":13,"constitution":19,"intelligence":4,"wisdom":13,"charisma":6,"baseatk":5,"cmb":5,"cmd":17,"feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Escape Artist","value":9},{"skill":"Perception","value":13}],"languages":["Aklo","Common","Draconic","Undercommon","telepathy 100 ft."],"environments":["any land (usually jungles or underground)"],"organizations":["solitary","pair","cult (3-12)"],"treasure":"none","description_visual":"This serpentine humanoid has bright scaly skin, a long sinuous tail, and a fanged serpent's head.","group":"Serpentfolk","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 16; frequency 1/round for 6 rounds; effect 1d2 Str; cure 2 saves. The save DC is Constitution-based."}],"description":"The majority of serpentfolk today are degenerates who have devolved to the point of primeval savagery and have lost much of their magical legacy-more civilized serpentfolk generally regard these degenerates with shame and disdain.\n\nDegenerates are 5 ft. tall but weigh 200 pounds.","ecology":"","habitat_society":"","gear":"dagger"},{"name":"Devilfish","cr":4,"xp":1200,"alignment":"NE","size":"Large","type":"magical beast","subtypes":["aquatic"],"init":3,"senses":[{"type":"low-light vision"},{"type":"see in darkness"}],"ac":17,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+3 Dex, +5 natural, -1 size","hp":42,"hd":"5d10+15","hdvalue":5,"fort":7,"ref":7,"will":12,"resists":[{"type":"cold","value":10}],"speed":[{"type":"land","speed":10},{"type":"swim","speed":40}],"speed_mod":"jet (240 ft.)","melee":"tentacles +7 (3d6+4 plus grab)","space":"10 ft.","reach":"15 ft.","special_attacks":[{"type":"savage bite","details":"+7 melee, 2d6+4/18-20 plus poison"},{"type":"unholy blood"}],"strength":17,"dexterity":17,"constitution":16,"intelligence":3,"wisdom":12,"charisma":8,"baseatk":5,"cmb":20,"cmd":33,"feats":[{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Escape Artist","value":5},{"skill":"Perception","value":5},{"skill":"Stealth","value":3},{"skill":"Swim","value":15}],"languages":["Abyssal","Aquan","Common"],"sq":[{"type":"water dependency"}],"environments":["any aquatic"],"organizations":["solitary"],"treasure":"none","description_visual":"This purple, seven-armed octopoid monstrosity is the size of a horse, with hook-lined tentacles and cold, blue eyes.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Poison","kind":"Ex","details":"Savage bite-injury; save Fort DC 15; frequency 1/round for 6 rounds; effect 1d2 Str; cure 2 consecutive saves."},{"type":"Savage Bite","kind":"Ex","details":"A devilfish can attack with its savage bite whenever it makes a successful grapple check. This attack is in place of any other action made with a successful grapple check. The bite threatens a critical hit on a roll of 18-20, and injects the target with poison as well."},{"type":"Unholy Blood","kind":"Su","details":"A devilfish's blood is infused with fiendish magic. Once per day, as a swift action, a devilfish can emit a night-black cloud of this foul liquid, filling a 20-foot-radius cloud if underwater, or a 20-foot-radius burst on land. In water, the blood provides total concealment for everything but a devilfish (which can see through the blood with ease); on land the slippery blood coats the ground, making the area difficult terrain. The blood persists for 1 minute before fading. Anyone who enters a cloud of the blood in the water or who is within the area of a burst of blood on land must make a DC 15 Fortitude save or be nauseated for 1d4 rounds-this save need be made only once per cloud. The save DC is Constitution-based."},{"type":"Water Dependency","kind":"Ex","details":"A devilfish can survive out of the water for 1 hour, after which it becomes fatigued. After 2 hours, the devilfish becomes exhausted and begins to suffocate."}],"description":"Although the devilfish superficially resembles a seven-armed octopus, it is an altogether different creature. Possessing a rudimentary intellect, a devilfish can understand and even speak a few words and phrases in various languages, although when it speaks, it has a tendency to mix languages together, making it somewhat difficult to understand for anyone who doesn't speak all the languages known by the devilfish.\n\nMore than those of a mere animal, the devilfish's intelligence and several of its abilities are gifts from a fiendish legacy-most sages believe that the original devilfish were once outsiders from the Abyss, and that over the course of thousands of years they became true natives of the Material Plane's oceans. Rumors of far more intelligent devilfish dwelling in the deepest ocean trenches persist, although if these rumors are true, these deep-dwelling devilfish don't often come to the surface.\n\nA devilfish is 10 ft. long and weighs 500 pounds.","ecology":"","habitat_society":""},{"name":"Dire Boar","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"animal","init":4,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":9,"ac_flat_footed":15,"ac_mods":"+6 natural, -1 size","hp":42,"hd":"5d8+20","hdvalue":5,"fort":7,"ref":4,"will":3,"defensive_abilities":["ferocity"],"speed":[{"type":"land","speed":40}],"melee":"gore +8 melee (2d6+9)","space":"5 ft.","reach":"5 ft.","strength":23,"dexterity":10,"constitution":17,"intelligence":2,"wisdom":13,"charisma":8,"baseatk":3,"cmb":3,"cmd":14,"feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":12}],"environments":["temperate forests","tropical forests"],"organizations":["solitary","pair","herd (3-8)"],"treasure":"none","description_visual":"The back of this horse-sized boar rises in a steep slope. Its tiny red eyes are crusted with filth and its bristly f lank crawls with f lies.","group":"Boar","source":"PFRPG Bestiary","description":"Whereas the boar is ill-tempered and generally unfriendly, the towering daeodon (known as the dire boar to most commoners and hunters) is legitimately hateful and violent. Although omnivorous like its smaller kin, the daeodon prefers to feed on flesh, and its razor-sharp tusks and keen eyesight make it particularly well suited as a predator. While the daeodon is primarily a scavenger, it isn't averse to attacking smaller creatures it encounters while searching for easier meals, or those who stumble unwittingly into its territory. Particularly brave or skilled orcs are fond of using daeodons as mounts, and orc cavalry mounted on dire boars make for a fearsome force indeed. A typical adult daeodon is 10 ft. long and 7 ft. tall at the shoulder. It weighs approximately 2,000 pounds.","ecology":"","habitat_society":""},{"name":"Dire Wolverine","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"animal","init":7,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":16,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+3 Dex, +4 natural, -1 size","hp":42,"hd":"5d8+20","hdvalue":5,"fort":7,"ref":7,"will":4,"speed":[{"type":"land","speed":30},{"type":"climb","speed":10}],"melee":"2 claws +6 (1d8+4), bite +6 (1d6+4)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"rage"}],"strength":19,"dexterity":17,"constitution":17,"intelligence":2,"wisdom":12,"charisma":10,"baseatk":3,"cmb":18,"cmd":31,"cmd_special":"+3 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":12},{"skill":"Perception","value":12}],"environments":["cold forests"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This terrible wolverine is as large as a bear, its jaws and claws oversized and brutal, its eyes dark and filled with rage.","group":"Wolverine","source":"PFRPG Bestiary","special_abilities":[{"type":"Rage","kind":"Ex","details":"A dire wolverine that takes damage in combat flies into a rage on its next turn, madly clawing and biting until either it or its opponent is dead. It gains +4 to Strength, +4 to Constitution, and -2 to AC. The creature cannot end its rage voluntarily."}],"description":"Dire wolverines tend to be even more territorial than their smaller wolverine cousins, and they defend to the death the areas where they choose to live, often selecting humanoidsettled regions as their own and then fearlessly tearing the settlements apart.\n\nDire wolverines grow to about 12 ft. in length and can weigh as much as 2,000 pounds.","ecology":"","habitat_society":""},{"name":"Dunagh","cr":4,"xp":1200,"alignment":"LN","size":"Medium","type":"outsider","subtypes":["incorporeal","kami","native"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["fate (20 ft., DC 15)"],"ac":16,"ac_touch":16,"ac_flat_footed":13,"ac_mods":"+3 deflection, +3 Dex","hp":37,"hd":"5d10+10","hdvalue":5,"hp_mods":["fast healing 2"],"fort":3,"ref":7,"will":7,"defensive_abilities":["incorporeal"],"immunities":["bleed","mind-affecting effects","petrification","polymorph"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"incorporeal touch +8 (2d6 cold plus dunagh's curse)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"mage hand"}]}],"dexterity":17,"constitution":14,"intelligence":11,"wisdom":17,"charisma":16,"baseatk":5,"cmb":28,"cmb_special":"+4 vs. grapple","cmd":38,"cmd_special":"+12 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Fly","value":19},{"skill":"Intimidate","value":11},{"skill":"Knowledge (local)","value":8},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":11}],"languages":["Common","telepathy 100 ft."],"sq":[{"type":"merge with ward"},{"type":"ward","details":"house"}],"environments":["any urban"],"organizations":["solitary"],"treasure":"standard","description_visual":"This spectral woman holds a silver urn and floats in midair with an unearthly grace and demanding presence.","source":"Daughters Of Fury","special_abilities":[{"type":"Aura of Fate","kind":"Su","details":"A dunagh merged with or within 120 ft. of its ward radiates an aura of fate to a radius of 20 ft. Enemies within this aura must roll two d20s whenever a situation calls for a d20 roll (such as an attack, a skill check, or a saving throw) and take the lower of the two results. Allies designated by the dunagh in this aura likewise roll two d20s whenever a situation calls for a d20 roll, but can take the higher result instead. This is a mind-affecting morale effect that doesn't work on fey. A dunagh can suppress and reactivate this aura at will as a free action."},{"type":"Dunagh's Curse","kind":"Su","details":"Any creature touched by a dunagh must succeed at a DC 15 Will save or be afflicted with the dunagh's curse. Whenever the cursed creature rolls a d20, it treats any roll of 20 as a roll of 1 instead. The cursed creature cannot take 20. The save DC is Charisma-based."}],"description":"Dunaghs, like most kami, are guardian spirits native to Tian Xia. Unlike others of their kind, however, dunaghs long ago attached themselves to caravans coming over the Crown of the World, eventually establishing themselves in\n\nthe Lands of the Linnorm Kings, where they're most likely to be found today. Attracted by a family's or clan's intense devotion to a single structure or holding, the dunaghs serve as guardians of family homes, watchful protectors of both the structures and those who live within them.\n\nMost dunaghs prefer to remain anonymous, going about their business when residents are not present. They occasionally assist \"their\" family by tidying up the house, locking doors, or shutting windows left open during the cold months.\n\nWhen a family line watched over by a dunagh comes to an end, the dunagh falls into a bleak depression and remains fixated on the family's last place of residence, becoming a spiteful spirit that forcibly evicts anyone else who tries to take up residence or otherwise trespass upon its ward.\n\nDunaghs prefer to stay merged with their wards, but in their visible forms, they take on appearances similar to ghostly versions of those people they guard.","ecology":"","habitat_society":""},{"name":"Dust Digger","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"aberration","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":16,"ac_touch":9,"ac_flat_footed":16,"ac_mods":"+7 natural, -1 size","hp":42,"hd":"5d8+20","hdvalue":5,"fort":5,"ref":1,"will":4,"speed":[{"type":"land","speed":10},{"type":"burrow","speed":20}],"melee":"bite +5 (1d8+3 plus grab), 5 tentacles +3 (1d4+1 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"sinkhole"},{"type":"swallow whole","details":"2d8+4 bludgeoning, AC 13, 4 hp"}],"strength":17,"dexterity":11,"constitution":18,"intelligence":2,"wisdom":11,"charisma":10,"baseatk":3,"cmb":7,"cmb_special":"+4 vs. grapple","cmd":17,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Perception","value":5},{"skill":"Stealth","value":5,"special":"+13 in ambush"}],"environments":["warm deserts"],"organizations":["solitary","pair","colony (3-10)"],"treasure":"none","description_visual":"A tremendous starfish-like creature emerges from the sand, its five long arms surrounding a circular toothy maw.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Sinkhole","kind":"Ex","details":"A dust digger can burrow into sand, loose soil, or dirt to lie in ambush just under the surface. When it feels (via tremorsense) prey walk into a square it threatens, it can deflate its body as an immediate action, causing the sand and other loose soil above to shift and slide. All creatures who were standing in the dust digger's reach must make a DC 15 Reflex save or become entangled as long as they remain in the dust digger's reach. All creatures who were standing at least partially in the dust digger's actual space must make a DC 15 Reflex save or become entangled and fall prone-if such a creature makes this save, it immediately moves to the closest adjacent unoccupied square. If this results in more than a 5-foot move, the creature moves that distance and then falls prone. The save DC is Strength-based."}],"description":"Dust diggers most resemble mammoth starfish, with thick sandy-colored exoskeletons covered with rough, burr-like spines. Its five arms are long and thin, and covered with hundreds of barbed, tubular cilia that the creature uses to move as well at grab and grapple prey. At the fleshy center of the creature's body gapes a circular maw lined with large sharp teeth.\n\nAs ambush predators, dust diggers spend the majority of their lives buried beneath the sand, waiting patiently for prey to stumble over their ambush site.\n\nDust diggers are asexual. They reproduce by budding, splitting off young three to four times over the course of their 10-year lives-smaller versions of themselves that must immediately move away from the parent to avoid being snatched up and eaten. Dust digger young are just over 4 ft. across, and can move relatively quickly through sand (their burrow speed is 40 ft.). Usually, a young dust digger travels at least a mile from its parent before it settles down to create its first ambush-the amount of life in the region it has chosen as its new lair often determines whether the new dust digger thrives or starves to death, for once it digs its first ambush, it rarely moves more than a few hundred ft. away over the course of its life.","ecology":"","habitat_society":""},{"name":"Dvorovoi","cr":4,"xp":1200,"alignment":"CN","size":"Small","type":"fey","init":3,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+3 Dex, +3 natural, +1 size","hp":38,"hd":"7d6+14","hdvalue":7,"fort":4,"ref":8,"will":0,"dr":"5/cold iron","sr":15,"speed":[{"type":"land","speed":30}],"melee":"pitchfork +6 (1d8+3)","ranged":"pitchfork +7 (1d8+3)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"speak with animals"}]},{"frequency":"at-will","spells":[{"spell":"charm animal"},{"spell":"hide from animals"},{"spell":"invisibility"}]},{"frequency":"1/day","spells":[{"spell":"entangle"}]},{"frequency":"3/day","spells":[{"spell":"break"},{"spell":"reduce person"}]}],"strength":15,"dexterity":16,"constitution":14,"intelligence":9,"wisdom":13,"charisma":16,"baseatk":3,"cmb":2,"cmd":12,"cmd_special":"+4 vs. bull rush or trip","feats":[{"feat":"Catch Off-Guard"},{"feat":"Combat Reflexes"},{"feat":"Throw Anything"},{"feat":"Two-Handed Thrower"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Bluff","value":10},{"skill":"Diplomacy","value":9},{"skill":"Handle Animal","value":13},{"skill":"Knowledge (nature)","value":5},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":6},{"skill":"Stealth","value":16},{"skill":"Survival","value":3}],"languages":["Common","Sylvan","speak with animals"],"sq":[{"type":"compression"},{"type":"oversized weapons"},{"type":"wild empathy","details":"+18"}],"environments":["any land"],"organizations":["solitary","gathering (2-6)"],"treasure":"none","description_visual":"A wild mop of hair tops this small humanoid creature's head. It has prominent, gleaming eyes, and a toothy grin.","source":"AP 67","special_abilities":[{"type":"Oversized Weapons","kind":"Ex","details":"A dvorovoi can wield weapons sized for Medium creatures without penalty."},{"type":"Wild Empathy","kind":"Ex","details":"This ability works like the druid ability of the same name. The dvorovoi's total bonus includes a +8 racial bonus."}],"description":"Just as the domovoi protect the home, the dvorovoi protect a villager's yard and pasture. Some farmers try to lure dvorovoi to their farmsteads by leaving an offering of bread, sheep's wool, or shiny trinkets. When the owner of a farmstead with a dvorovoi purchases a new animal, he leads it through the yard to introduce it to the dvorovoi, hoping to gain the fey creature's approval of the new livestock.\n\nThough undeniably useful to have around for feeding the cattle and keeping predators away from flocks, dvorovoi can be capricious. Dvorovoi despise any white animal, and will never tolerate a white-furred horse or cow in their presence. For unknown reasons, dvorovoi doesn't hold this same grudge toward white chickens.","ecology":"","habitat_society":""},{"name":"Emerald Automaton","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"construct","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["electricity (5 ft., DC 12)"],"ac":17,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+1 Dex, +6 natural","hp":47,"hd":"5d10+20","hdvalue":5,"fort":1,"ref":2,"will":1,"dr":"5/adamantine","immunities":["construct traits"],"weaknesses":["magic dependent"],"speed":[{"type":"land","speed":30}],"melee":"guisarme +10 (2d4+7/x3) or  longsword +10 (1d8+5/19-20), slam +5 (1d4+2)","space":"5 ft.","reach":"5 ft. (10 ft. with guisarme)","strength":20,"dexterity":13,"wisdom":11,"charisma":1,"baseatk":5,"cmb":10,"cmb_special":"+2 vs. sunder","cmd":21,"cmd_special":"+2 vs. sunder","feats":[{"feat":"Improved Sunder","type":"bonus"},{"feat":"Power Attack","type":"bonus"}],"sq":[{"type":"proficient"}],"environments":["any"],"organizations":["solitary","pair","squad (3-8)"],"treasure":"incidental (guisarme)","description_visual":"An eerie green glow shines through the seams of this mechanical creature's armor.","source":"The Emerald Spire","special_abilities":[{"type":"Electricity Aura","kind":"Su","details":"An emerald automaton reduced to half its hit points or fewer emits hazardous energy from its damaged magical battery. Any non-construct creature that ends its turn within 5 ft. of a damaged emerald automaton takes 1d10 points of electricity damage (Reflex DC 12 negates). The save DC is Constitution-based."},{"type":"Magic Dependent","kind":"Su","details":"An emerald automaton is partially powered by magic. When deprived of magic, the automaton is affected as if it were exhausted. The automaton's magic can be cut off by antimagic, or suppressed by a dispel magic or mage's disjunction effect as if it were a magic item."},{"type":"Proficient","kind":"Ex","details":"An emerald automaton is proficient with all simple and martial weapons."}],"description":"Like other constructs, an emerald automaton is a mindless, unliving machine that exists only to follow the orders of its creator. It is a capable soldier and can wield almost any weapon its creator chooses to provide it, fighting until it or its target is destroyed.\n\nIn combat, emerald automatons often wield polearms and make use of their reach. When multiple automatons are fighting together, it's common for one to sunder a target's shield or weapon and the rest to gang up\n\nagainst the target. Getting inside the reach of an emerald automaton is no guarantee of safety-the constructs are quite strong, and can strike with a powerful slam attack at need. When badly damaged, an emerald automaton begins to emit crackling green sparks of electricity that can severely shock nearby creatures.\n\nConstruction\n\nAn emerald automaton begins as an articulated iron frame connected with thick copper wiring, and is then covered by armored plates. These materials cost at least 500 gp. The creator must then use a fist-sized shard of crystal from the Emerald Spire as the automaton's main battery, placing it in the construct's hollow chest.\n\nEMERALD AUTOMATON\n\nCL 6th; Price 12,000 gp\n\nConstruction\n\nRequirements Craft Construct, lesser geas, shocking grasp, creator must be caster level 6th; Skill Craft (armor) DC 20; Cost 6,500 gp","ecology":"","habitat_society":""},{"name":"Faceless Stalker","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"aberration","subtypes":["shapechanger"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+3 Dex, +4 natural","hp":42,"hd":"5d8+20","hdvalue":5,"fort":5,"ref":4,"will":6,"dr":"5/piercing or slashing","speed":[{"type":"land","speed":30}],"melee":"mwk longsword +8 (1d8+4/19-20), slam +2 (1d6+2 plus grab)","space":"5 ft.","reach":"10 ft.","special_attacks":[{"type":"blood drain","details":"1 Constitution"},{"type":"sneak attack","details":"+2d6"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"tongues"}]}],"strength":18,"dexterity":17,"constitution":18,"intelligence":13,"wisdom":15,"charisma":16,"baseatk":3,"cmb":7,"cmb_special":"+4 vs. grapple","cmd":20,"feats":[{"feat":"Combat Reflexes"},{"feat":"Deceitful"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Disguise","value":14,"special":"+24 when using change shape"},{"skill":"Escape Artist","value":19},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":11}],"languages":["Aquan","Common","tongues"],"sq":[{"type":"change shape","details":"Medium humanoid, alter self"},{"type":"compression"},{"type":"faceless"}],"environments":["any swamps","any underground"],"organizations":["solitary","pair","gang (3-9)"],"treasure":"standard (masterwork longsword)","description_visual":"This hairless, leathery biped has a face dominated by grotesque and unsettling whorls and slits instead of actual features.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Change Shape","kind":"Su","details":"A faceless stalker can assume the form of a Medium humanoid at will but requires 10 uninterrupted minutes to alter its body. Performing this transformation is somewhat painful, but the faceless stalker can maintain its new form indefinitely once it has achieved it. It can change back to its true form as a swift action and gains a +2 morale bonus on attack rolls, damage rolls, skill checks, and saving throws for 1 round after it does so. Faceless stalkers retain their own innate abilities when they assume their new form and don't gain any of those belonging to the creature they mimic. A faceless stalker gains a +10 bonus on Disguise checks when they are used in conjunction with this ability."},{"type":"Faceless","kind":"Su","details":"In its natural form, a faceless stalker has no discernible facial features. It gains a +4 bonus on saving throws made to resist attacks or effects that target the senses. This includes gaze attacks, odor-based attacks, sonic attacks and similar attacks. This bonus doesn't apply to illusions."}],"description":"Ugothols (as faceless stalkers call themselves) are one of the many tools created and then discarded by the aboleths in their long war against the surface dwellers. Scorned by their former masters when the scheme for which they were designed unraveled, the faceless stalkers fled into swamps, marshes, or any other dark, wet places they could find-the closest they could come to the aquatic cities they once considered home.\n\nOriginally designed to serve as spies that could walk uncontested among the air-breathing races, faceless stalkers adopt new forms by reshaping their skin and contorting their rubbery bodies. This painful process takes approximately 10 uninterrupted minutes-an ugothol typically seeks a private place to do it, avoiding even others of its own kind. The sensation of returning to its true form is quite exhilarating and results in a momentary burst of euphoria.\n\nFaceless stalkers cannot digest solid food even when in the form of a creature with a mouth. Instead, they subsist on liquids, including blood. In their natural forms, they have three hollow tongues which they use to penetrate and lap blood from their victims. Since they have no particular skill at grappling foes, most ugothols wait until a victim is helpless or asleep before attempting to drink its blood-although the best is when a victim is helpless but conscious during the process, so that the faceless stalker can \"play with its food\" by having grisly and cruel conversations with it.","ecology":"","habitat_society":""},{"name":"Flail Snail","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"magical beast","init":-1,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"},{"type":"tremorsense","modifier":"60 ft."}],"ac":18,"ac_touch":8,"ac_flat_footed":18,"ac_mods":"-1 Dex, +10 natural, -1 size","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":3,"will":2,"defensive_abilities":["retraction","warp magic"],"immunities":["poison"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":10},{"type":"climb","speed":10}],"melee":"4 slams +7 (1d4+3)","space":"10 ft.","reach":"10 ft.","strength":16,"dexterity":8,"constitution":14,"intelligence":5,"wisdom":12,"charisma":8,"baseatk":4,"cmb":8,"cmd":17,"cmd_special":"can't be tripped","feats":[{"feat":"Power Attack"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Climb","value":15},{"skill":"Perception","value":5},{"skill":"Stealth","value":0}],"languages":["Flail Snail (sign language, slime writing, cannot speak)"],"sq":[{"type":"mucus"},{"type":"slime rope"},{"type":"suction"}],"environments":["any underground"],"organizations":["solitary","pair","rout (3-30)"],"treasure":"standard (shell worth 800 gp)","description_visual":"This enormous snail has a brightly colored shell and four tentacles on its head, each tipped with a mace-like club.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Mucus","kind":"Ex","details":"As a free action, a flail snail can excrete a trail of mucus that covers its space and lasts for 10 minutes. This mucus comes in two types: slimy and sticky. A character who attempts to move through an area covered in slippery mucus must make a DC 14 Reflex save each round or fall prone. Sticky mucus transforms squares into difficult terrain. Only one type of mucus can be in effect at a time in any one square. Flail snails can move through either type of slime with ease. A square of mucus exposed to a fire source dries and reverts to normal. The save DC is Constitution-based."},{"type":"Retraction","kind":"Ex","details":"A flail snail can pull its fleshy parts into its shell as a swift action, increasing its natural armor bonus by +6, but it cannot move or attack while retracted. It can return to normal as a free action."},{"type":"Slime Rope","kind":"Ex","details":"A flail snail can turn its mucus into a ropelike strand up to 60 ft. long, and can use this rope to hang itself and up to 1,000 extra pounds from the ceiling indefinitely, or to lower itself safely at a speed of 20 ft. per round. It can climb back up this rope at a speed of 10 ft. per round. Once the snail breaks contact with the rope, the slime decomposes in 1d4 rounds. While the slime rope exists, other creatures can climb the rope with a DC 20 Climb check."},{"type":"Suction","kind":"Ex","details":"A flail snail's foot adheres to surfaces so well that its 10-foot climb speed applies even to perfectly sheer surfaces and ceilings, with no chance of the flail snail falling off unless it is actively pinned and peeled away as part of a grapple."},{"type":"Warp Magic","kind":"Su","details":"Anytime a spell targets a flail snail, there is an 80% chance that it produces a random effect instead of affecting the snail. Only spells that directly target the flail snail are warped; area effect spells are not affected. If a spell is warped, roll 1d10 and consult the following table. 1-3 Spell misfires. For the next 1d4 rounds, the caster must make a DC 15 concentration check to successfully cast spells. 4-6 Spell misfires. The creature nearest the flail snail is affected as if the spell had been cast on it instead. 7-9 Spell fails. Nothing happens. 10 Spell rebounds on caster (as spell turning)."}],"description":"Flail snails are intelligent gastropods that subsist on fungus, mold, and vermin, though they may attack larger creatures in self-defense. Known for their magic-warping shells and club-like tentacles, flail snails roam slowly through subterranean caverns writing great epics in their slime trails.","ecology":"","habitat_society":""},{"name":"Forest Drake","cr":4,"xp":1200,"alignment":"LE","size":"Large","type":"dragon","subtypes":["earth"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+2 Dex, +6 natural, -1 size","hp":42,"hd":"5d12+10","hdvalue":5,"fort":6,"ref":6,"will":4,"immunities":["acid","paralysis","sleep"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"average"},{"type":"swim","speed":30}],"melee":"bite +8 (1d8+4), tail slap +3 (1d8+2)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"acidic cloud"}],"strength":19,"dexterity":14,"constitution":14,"intelligence":9,"wisdom":11,"charisma":12,"baseatk":5,"cmb":10,"cmd":22,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":8},{"skill":"Intimidate","value":9},{"skill":"Perception","value":11},{"skill":"Stealth","value":6},{"skill":"Swim","value":20}],"languages":["Draconic"],"sq":[{"type":"aquatic adaptation"},{"type":"speed surge"}],"environments":["any forests"],"organizations":["solitary","pair","rampage (3-12)"],"treasure":"standard","description_visual":"This green-scaled dragon has two powerful legs and a pair of long, leathery wings. A long spike adorns its thrashing tail.","group":"Drake","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Acidic Cloud","kind":"Su","details":"A forest drake can, as a standard action, spit a ball of acid that bursts into a cloud on impact. This attack has a range of 60 ft. and deals 4d6 points of acid damage (Reflex DC 14 half) to all creatures within the resulting 10-foot-radius spread. The cloud remains for 1d4 rounds once created, acting as a 10-foot-radius obscuring mist (it no longer causes damage), but a strong wind disperses it in a single round. Once a forest drake has used its acidic cloud breath, it cannot do so again for 1d6 rounds. The Reflex save is Constitution-based."},{"type":"Aquatic Adaptation","kind":"Ex","details":"A forest drake can breathe underwater indefinitely and can freely use its breath weapon and other abilities while underwater. The acidic cloud created by that attack dissipates after 1 round if used underwater."},{"type":"Speed Surge","kind":"Ex","details":"Three times per day as a swift action, a forest drake may draw on its draconic heritage for a boost of strength and speed to take an additional move action in that round."}],"description":"Forest drakes are the degenerate cousins of green dragons, possessed of cruel cunning but little actual wit. Like most drakes, forest drakes are bullies, prowling deep forests in search of their favorite prey-elves and fey. Forest drakes eagerly attack communities of such forest creatures unless driven off with arrows or other shows of force.\n\nLike many other drake types, forest drakes organize themselves in packs called \"rampages,\" and keep communal lairs in secluded forest locations. Such packs are usually made up of siblings who break from the pack only during mating season. A forest drake pack has a distinct pecking order, with younger and newer members receiving the least desirable portions of pack kills and the fewest mating options.\n\nForest drakes mate once a year, but do little to raise their offspring. A female lays a clutch of four to eight eggs, but abandons her young as soon as they hatch. Forest drake hatchlings immediately band together in a pack.\n\nWhile few survive so long, forest drakes can live up to 200 years. Forest drakes are typically about 10 ft. long with equally long tails, and weigh around 1,000 pounds.","ecology":"","habitat_society":""},{"name":"Fossegrim","cr":4,"xp":1200,"alignment":"NE","size":"Medium","type":"fey","subtypes":["aquatic"],"init":7,"senses":[{"type":"low-light vision"}],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+3 Dex, +1 dodge, +4 natural","hp":41,"hd":"9d6+19","hdvalue":9,"fort":5,"ref":9,"will":8,"dr":"5/cold iron","speed":[{"type":"land","speed":30},{"type":"swim","speed":40}],"speed_mod":"water walk","melee":"2 slams +8 (2d6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"drowning touch","details":"DC 14"},{"type":"enchanting music","details":"DC 19"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"water walk"}]},{"frequency":"3/day","spells":[{"spell":"hydraulic torrent"}]}],"strength":10,"dexterity":17,"constitution":15,"intelligence":12,"wisdom":14,"charisma":21,"baseatk":4,"cmb":4,"cmd":17,"feats":[{"feat":"Alertness"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Bluff","value":17},{"skill":"Diplomacy","value":9},{"skill":"Knowledge (geography)","value":6},{"skill":"Knowledge (nature)","value":10},{"skill":"Perception","value":16},{"skill":"Perform (sing)","value":10},{"skill":"Perform (string)","value":21},{"skill":"Sense Motive","value":16},{"skill":"Sleight of Hand","value":10},{"skill":"Stealth","value":15},{"skill":"Swim","value":18}],"languages":["Common","Sylvan"],"sq":[{"type":"amphibious"},{"type":"transparency"},{"type":"treasure form"}],"environments":["cold water (waterfalls)","temperate water (waterfalls)"],"organizations":["solitary"],"treasure":"standard (mwk harp or violin)","description_visual":"This striking, blue-eyed man with luminous skin and flowing white hair holds an ethereal harp.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Drowning Touch","kind":"Su","details":"A fossegrim can flood the lungs of a creature that is willing, is helpless, is affected by its enchanted music ability, touches it while it's in treasure form, or is touched by it (traditionally by kissing the creature on the lips). If the target cannot breathe water, it cannot hold its breath and immediately begins to drown slowly. On its turn, the target can attempt a DC 16 Fortitude save to cough up this water; if it fails, it falls unconscious at 0 hp. On the next round, a fallen target must attempt another DC 16 Fortitude save, dropping to -1 hit points and dying if it fails; on the next round it must attempt to save again or lose 1d6 hit points. On the first successful save, the water clears from the target's lungs and the target stabilizes. The save DC is Constitution-based."},{"type":"Enchanting Music","kind":"Su","details":"As a full-round action, a fossegrim can play a musical stringed instrument (usually a harp or violin) and target a single creature within 45 ft. that can hear and see the fossegrim with an effect identical to the unnatural lust spell (CL 9th; Will DC 19). This action provokes an attack of opportunity. If the target touches or kisses the fossegrim, the fey can affect the target with its drowning touch ability. This is a sonic mind-affecting compulsion effect. The save DC is Charisma-based."},{"type":"Transparency","kind":"Su","details":"When underwater, a fossegrim's body becomes transparent, effectively rendering it invisible. It can become visible or transparent at will as a free action."},{"type":"Treasure Form","kind":"Su","details":"As a standard action when completely underwater, a fossegrim can create an illusion causing it to resemble a Medium pile of gold and silver coins, glittering jewels, and valuable art objects. If a fossegrim speaks, moves, attacks, or uses any of its special abilities or spell-like abilities while in treasure form, the illusion dissipates. A successful DC 19 Will save is required to disbelieve this illusion. If a living creature within the fossegrim's melee reach touches or physically interacts with the illusion, the fossegrim reaches out to kiss or otherwise touch that creature, automatically affecting the creature with its drowning touch ability. The fossegrim can maintain this illusion indefinitely and can revert to its normal natural form as a free action. This is a mind-affecting illusion (glamer) effect. The save DC to disbelieve is Charisma-based."}],"description":"Pale and possessing unnatural beauty, fossegrims are wicked fey who haunt idyllic waterfalls, where they lure the unsuspecting near with song and the promise of treasure, only to drown them. Well built and elf like in appearance, fossegrims are gifted musicians, and their lairs often echo with the sound of bewitching music. They are never without their enchanting instruments.","ecology":"","habitat_society":""},{"name":"Freezing Flow","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"ooze","subtypes":["cold","water"],"init":-5,"senses":[{"type":"blindsense","modifier":"60 ft."}],"ac":16,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+3 Dex, +4 natural, -1 size","hp":47,"hd":"5d8+25","hdvalue":5,"fort":6,"ref":3,"will":-4,"immunities":["cold","ooze traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":20}],"melee":"slam +6 (2d4+6/19-20 plus 1d6 cold and grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"2d4+6 plus 1d6 cold"},{"type":"jagged slam"},{"type":"numbing touch"}],"strength":18,"dexterity":16,"constitution":20,"wisdom":1,"charisma":1,"baseatk":3,"cmb":8,"cmd":13,"skills":[{"skill":"Swim","value":12}],"sq":[{"type":"crystalline"}],"environments":["any cold"],"organizations":["solitary"],"treasure":"none","description_visual":"This transparent blue formation of ice is as forbidding as the serpent it resembles.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Crystalline","kind":"Ex","details":"As a creature of living ice, a freezing flow is difficult to discern from its surroundings in icy and snowy land environments and when in icy water. A successful DC 15 Perception check is required to notice a freezing flow in these environments. Any creature that fails to notice a freezing flow and walks into it automatically takes damage as if struck by the ooze's slam attack."},{"type":"Jagged Slam","kind":"Ex","details":"A freezing flow's slam attack is a slashing tendril of crystalline ice. It deals slashing damage instead of bludgeoning damage and has a critical range of 19-20."},{"type":"Numbing Touch","kind":"Ex","details":"Each time a freezing flow deals cold damage with its slam attack or constrict ability, the target must succeed at a DC 17 Fortitude save or be staggered with numbing cold for 1 round. The save DC is Constitution-based."}],"description":"It's believed that these strange frozen oozes are created when a particularly cold arctic area has prolonged exposure to ice from the Elemental Planes. Rising seemingly spontaneously from such a supernatural deep freeze, freezing flows shamble forth in search of prey, hungry for the life energy of warm-blooded creatures, which they somehow metabolize. Within their native habitat, these oozes are particularly difficult to spot. While they lack intelligence, they have an instinct to stay put within frozen ice flows, on the icy surface of frozen lakes and rivers, or within areas of permafrost, waiting for prey to stumble upon them. This instinct may be tied to the fact that they can stay relatively dormant for decades or even centuries, but eventually they need the life energy of warm-blooded creatures to fuel their strange locomotion. Since they dwell in unforgiving and underpopulated areas, it is easier for them to conserve energy and wait for prey rather than to try to track down warm-blooded creatures. After feeding, or when fully fed, these creatures tend to ignore other creatures unless attacked. Though freezing flows' crystalline construction can give the illusion that they are brittle, nothing is further from the truth. When a freezing flow slams into flesh, it does so with enough power to break bone, and it is cold enough to numb flesh, causing its prey to convulse in a fit of shivers. When hungry, the only things freezing flows avoid are fire and high temperatures. Such things can still melt and damage a freezing flow, though it typically requires more heat to diminish a freezing flow into a puddle of water than it takes to melt a patch of normal ice 10 times the ooze's size.","ecology":"","habitat_society":""},{"name":"Frost Wight","cr":4,"xp":1200,"alignment":"LE","size":"Medium","type":"undead","subtypes":["cold"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+1 Dex, +4 natural","hp":26,"hd":"4d8+8","hdvalue":4,"fort":3,"ref":2,"will":5,"defensive_abilities":["undead traits"],"weaknesses":["resurrection vulnerability"],"speed":[{"type":"land","speed":30}],"melee":"slam +4 (1d4+1 plus 1d6 cold plus energy drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn"},{"type":"energy drain","details":"1 level, DC 14"}],"strength":12,"dexterity":12,"intelligence":11,"wisdom":13,"charisma":15,"baseatk":3,"cmb":4,"cmd":15,"feats":[{"feat":"Blind-Fight"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Intimidate","value":9},{"skill":"Knowledge (religion)","value":7},{"skill":"Perception","value":11},{"skill":"Stealth","value":16}],"languages":["Common"],"sq":[{"type":"create spawn"},{"type":"cold"}],"environments":["any"],"organizations":["solitary","pair","gang (3-6)","pack (7-12)"],"treasure":"standard","description_visual":"The pale flesh of this walking corpse is rotting and putrid, its body skeletal in places, ice and frost cling to its hair, and its eye sockets glow with blue-white light.","group":"Frost","source":"PFRPG Bestiary","special_abilities":[{"type":"Cold","kind":"Su","details":"A creature touching a frost wight with natural weapons or unarmed strikes takes 1d6 cold damage."},{"type":"Create Spawn","kind":"Su","details":"Any humanoid creature that is slain by a wight becomes a wight itself in only 1d4 rounds. Spawn so created are less powerful than typical wights, and suffer a -2 penalty on all d20 rolls and checks, as well as -2 hp per HD. Spawn are under the command of the wight that created them and remain enslaved until its death, at which point they lose their spawn penalties and become full-fledged and free-willed wights. They don't possess any of the abilities they had in life."},{"type":"Resurrection Vulnerability","kind":"Su","details":"A raise dead or similar spell cast on a wight destroys it (Will negates). Using the spell in this way doesn't require a material component."}],"description":"Wights are humanoids who rise as undead due to necromancy, a violent death, or an extremely malevolent personality. In some cases, a wight arises when an evil undead spirit permanently bonds with a corpse, often the corpse of a slain warrior. They are barely recognizable to those who knew them in life; their flesh is twisted by evil and undeath, the eyes burn with hatred, and the teeth become beast-like. In some ways, a wight bridges the gap between a ghoul and a spectre-a warped animated corpse whose touch steals living energy.","ecology":"","habitat_society":""},{"name":"Gargoyle","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"monstrous humanoid","subtypes":["earth"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+2 Dex, +4 natural","hp":42,"hd":"5d10+15","hdvalue":5,"fort":4,"ref":6,"will":4,"dr":"10/magic","speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"2 claws +7 (1d6+2), bite +7 (1d4+2), gore +7 (1d4+2)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":14,"constitution":16,"intelligence":6,"wisdom":11,"charisma":7,"baseatk":5,"cmb":7,"cmd":19,"feats":[{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Fly)"}],"skills":[{"skill":"Fly","value":12},{"skill":"Perception","value":5},{"skill":"Stealth","value":11,"special":"+17 in stony areas"}],"languages":["Common","Terran"],"sq":[{"type":"freeze"}],"environments":["any"],"organizations":["solitary","pair","wing (3-12)"],"treasure":"standard","description_visual":"Seemingly carved from a dark gray stone, this sinister crouching humanoid resembles a horned, winged demon.","source":"PFRPG Bestiary","special_abilities":[{"type":"Freeze","kind":"Ex","details":"A gargoyle can hold itself so still it appears to be a statue. A gargoyle that uses freeze can take 20 on its Stealth check to hide in plain sight as a stone statue."}],"description":"Gargoyles often appear to be winged stone statues, for they can perch indefinitely without moving, allowing them to surprise their foes.\n\nGargoyles tend toward obsessive-compulsive behaviors that are as varied as their kind is plentiful.\n\nBooks, stolen trinkets, weapons, and grisly trophies harvested from fallen foes are just a few examples of the types of things a gargoyle might collect to decorate its lair and territory. Gargoyles tend toward a solitary lifestyle, though they sometimes form fearsome groups called \"wings\" for protection and sport. In certain conditions, a tribe of gargoyles might even ally with other creatures, but even the most stable alliances with a gargoyle tribe can collapse for the smallest of reasons-gargoyles are nothing if not treacherous, petty, and vindictive.\n\nGargoyles have been known to dwell in the heart of the largest of cities, crouching amid the decorations of stone cathedrals and buildings where they hide in plain sight by day and swoop down to feed on vagabonds, beggars, and other unfortunates at night.\n\nThe longer a tribe of gargoyles abides in a region of ruins or buildings, the more its members come to resemble that region's architectural styles. The changes a gargoyle's appearance undergoes are slow and subtle, but over the course of years, it can shift radically.\n\nOne unusual variant of gargoyle dwells not amid buildings and ruins but under the waves of the sea. These creatures are known as kapoacinths-they have the same basic statistics as normal gargoyles, save that they have the aquatic subtype and their wings grant them a swim speed of 60 ft. (but are useless for actual flight). Kapoacinths dwell in shallow, coastal regions where they can shamble up from the surf to prey on those that reside there. They are more likely to form wings, as kapoacinths prefer group living to a solitary lifestyle.","ecology":"","habitat_society":""},{"name":"Gearsman Robot","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"construct","subtypes":["robot"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":11,"ac_flat_footed":19,"ac_mods":"+1 Dex, +9 natural","hp":42,"hd":"4d10+20","hdvalue":4,"fort":1,"ref":2,"will":2,"defensive_abilities":["hardness 10"],"immunities":["construct traits"],"weaknesses":["vulnerable to critical hits","vulnerable to electricity"],"speed":[{"type":"land","speed":20}],"melee":"slam +9 (1d4+7) or   mwk spear +10 (1d8+5/x3 plus 1d6 electricity)","ranged":"mwk spear +6 (1d8+6/x3)","space":"5 ft.","reach":"5 ft.","strength":20,"dexterity":13,"intelligence":10,"wisdom":13,"charisma":1,"baseatk":4,"cmb":9,"cmd":20,"feats":[{"feat":"Combat Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Craft (any one)","value":8},{"skill":"Disable Device","value":8},{"skill":"Perception","value":8},{"skill":"Profession (any one)","value":7},{"skill":"Sense Motive","value":8}],"languages":["Common","Hallit"],"sq":[{"type":"adaptive learning"},{"type":"charge weapon"},{"type":"self-repair"}],"environments":["any (Numeria)"],"organizations":["solitary","pair","squad (3-12)"],"treasure":"standard (masterwork spear)","description_visual":"Made of what appears to be burnished brass, this construct resembles a suit of armor with a glowing glass orb for an eye.","group":"Robot","source":"Inner Sea Bestiary","special_abilities":[{"type":"Adaptive Learning","kind":"Ex","details":"A gearsman has a number of skill points equal to 4 + its Int modifier per Hit Die, and treats Craft and Profession as class skills beyond those possessed by all robots. In addition, a gearsman has a number of bonus skill ranks equal to its Hit Dice that can be reprogrammed to apply to any skill-these ranks cannot be split among multiple skills and must all apply to one skill. A gearsman may change what skill these bonus ranks apply to up to once per day by concentrating for 1 minute, during which time it can take no other actions. Rather than spend these bonus ranks on a skill, a gearsman can choose to devote them to weapon knowledge, gaining proficiency with a single weapon instead of bonus ranks in a skill. All gearsmen are automatically proficient with all simple weapons."},{"type":"Charge Weapon","kind":"Ex","details":"Any metal melee weapon wielded by a gearsman becomes charged with electricity and deals +1d6 points of electricity damage on a hit."},{"type":"Self-Repair","kind":"Ex","details":"A gearsman's nanites heal it of damage at the rate of a number of hit points per hour equal to its Hit Dice (4 hit points per hour for most gearsmen). Up to once per day, as a full-round action, it can heal any robot it touches of 4d6 points of damage-if a gearsman uses this ability on itself, it automatically heals the maximum amount: 24 points of damage."}],"description":"Of all the impossible artifacts of Silver Mount, none has been a greater boon to the Technic League than the fabled gearsmen. For reasons known only to themselves, many of these robots serve the artificers of the Technic League as shock troops and guards, performing their tasks with mechanical detachment and coldly logical efficiency. Yet they serve a purpose beyond Numeria, disobeying their putative masters whenever orders contradict their mysterious internal directives. When questioned about their lapses, a gearsman answers only with endlessly patient silence.","ecology":"","habitat_society":""},{"name":"Giant Dragonfly","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 Dex, +5 natural","hp":45,"hd":"7d8+14","hdvalue":7,"fort":7,"ref":4,"will":3,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":80,"maneuverability":"perfect"}],"melee":"bite +9 (2d8+6 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"darting charge"}],"strength":19,"dexterity":15,"constitution":14,"wisdom":12,"charisma":9,"baseatk":5,"cmb":9,"cmb_special":"+4 vs. grappling, +8 vs. grappling on a charge","cmd":21,"cmd_special":"+8 vs. trip","feats":[{"feat":"Flyby Attack","type":"bonus"}],"skills":[{"skill":"Fly","value":10}],"environments":["temperate land","warm land"],"organizations":["solitary","flight (2-5)"],"treasure":"incidental","description_visual":"This glittering blue dragonf ly is about the size of a horse and is large enough to carry off small farm animals or people.","group":"Dragonfly","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Darting Charge","kind":"Ex","details":"A giant dragonfly is adept at swooping in to attack prey with a powerful bite and then, just as quickly, swooping back up out of reach. As a result, a giant dragonfly gains Flyby Attack as a bonus feat. In addition, if a giant dragonfly charges while flying, it receives a +4 bonus on CMB checks made to grapple foes."}],"description":"Giant dragonflies are rare compared to other varieties of giant insects, and fortunately so, since they are voracious hunters of warm-blooded prey, including humanoids.\n\nThe creatures typically lair in overgrown or lightly wooded areas, using foliage as cover. When they spot potential prey out in the open, the dragonf lies swoop to the attack, using their superior flight speed and maneuverability to run most prey to ground or carrying off smaller foes to eat them somewhere safe. Giant dragonf lies feed on carrion when fresh prey isn't available, and the scent of a fresh kill often attracts them.\n\nMany swamp-dwelling cultures attach religious significance to brightly colored and ravenous giant dragonf lies, particularly boggards. The frog-men attach particular significance to a giant dragonf ly's color, and their priest-kings often refuse to eat anything but specific colors of giant dragonf lies.","ecology":"","habitat_society":""},{"name":"Giant Ground Wasp","cr":4,"xp":1200,"alignment":"N","size":"Small","type":"vermin","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+4 Dex, +2 natural, +1 size","hp":39,"hd":"6d8+12","hdvalue":6,"fort":7,"ref":6,"will":2,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":10},{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"bite +7 (1d6+2), sting +7 (1d4+2 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"implant"},{"type":"poison"}],"strength":15,"dexterity":19,"constitution":15,"wisdom":10,"charisma":2,"baseatk":4,"cmb":5,"cmd":19,"cmd_special":"+8 vs. trip","skills":[{"skill":"Fly","value":6},{"skill":"Perception","value":4}],"environments":["warm deserts"],"organizations":["solitary","hive (2-20)"],"treasure":"none","description_visual":"Black and yellow stripes cover this winged insect's bulbous abdomen, which ends in a dagger-sized stinger.","group":"Ground Wasp","source":"AP 81","special_abilities":[{"type":"Implant","kind":"Ex","details":"Ground wasps grow their eggs inside of a living host. Implanting eggs in a host is a full-round action that provokes attacks of opportunity, and the target must be helpless but alive. Once an egg is implanted, it exudes paralytic enzymes that not only keep the victim in a state of perpetual paralysis, but also keep it nourished and alive- and fully aware. This condition lasts until the egg hatches 1d6 days later, at which point the larvae consume most of the host, killing it. Any magical effect that removes paralysis or disease (such as remove paralysis, remove disease, or heal) destroys the eggs, but mere immunity to paralysis or disease doesn't offer protection."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 15; frequency 1/round for 6 rounds; effect 1d4 Dex damage; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"In areas of dense vegetation, ground wasps can destroy crops and ruin the land with their burrows, but in the rocky and sandy desert, living creatures are most at risk from these dangerous vermin. The blistering heat of the desert can damage delicate eggs laid in exposed locations, so ground wasps have evolved to lay their eggs safely in the bodies of their victims. They keep to their shallow burrows during the hottest parts of the day, but remain near the opening to ambush creatures that wander near. A fully-grown ground wasp is 2 ft. long, with a wingspan of 5 ft., and weighs 22 pounds.","ecology":"","habitat_society":""},{"name":"Giant Phantom Armor","cr":4,"xp":1200,"alignment":"NE","size":"Large","type":"undead","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+9 armor, -1 size","hp":37,"hd":"5d8+15","hdvalue":5,"fort":3,"ref":1,"will":4,"defensive_abilities":["channel resistance +4"],"immunities":["undead traits"],"speed":[{"type":"land","speed":20}],"melee":"heavy flail +7 (2d8+7/19-20)","space":"10 ft.","reach":"10 ft.","strength":20,"dexterity":11,"intelligence":7,"wisdom":11,"charisma":15,"baseatk":3,"cmb":9,"cmd":19,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":8},{"skill":"Stealth","value":4}],"languages":["Common (can't speak)"],"sq":[{"type":"freeze","details":"suit of armor"}],"environments":["any"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This suit of armor moves with a warrior's deadly skill despite obviously being empty.","group":"Phantom Armor","source":"PFRPG Bestiary 4","description":"Arising from the armored remains of towering humanoids, these suits are particularly fearsome, though slower than guardian phantom armors.\n\nCREATING PHANTOM ARMORS Phantom armors are created using the spell create undead. Creating a phantom armor requires a corpse wearing a suit of heavy armor. The corpse is destroyed in the phantom armor's creation. A magic-user must be at least caster level 12th to create a guardian phantom armor and at least caster level 15th to create a giant phantom armor.","ecology":"","habitat_society":""},{"name":"Giant Stag Beetle","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"vermin","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":9,"ac_flat_footed":17,"ac_mods":"+8 natural, -1 size","hp":45,"hd":"7d8+14","hdvalue":7,"fort":7,"ref":2,"will":2,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":20,"maneuverability":"poor"}],"melee":"bite +8 (2d8+6)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"trample","details":"1d6+6, DC 17"}],"strength":19,"dexterity":10,"constitution":15,"wisdom":10,"charisma":9,"baseatk":5,"cmb":10,"cmd":20,"cmd_special":"+8 vs. trip","skills":[{"skill":"Fly","value":-6}],"environments":["temperate forests"],"organizations":["solitary","pair","cluster (3-6)"],"treasure":"none","description_visual":"With a sleek body and huge mandibles raised in a threatening pose, this large beetle stands firm in defense of its territory.","group":"Beetle","source":"PFRPG Bestiary","description":"Nearly 10 ft. long, giant stag beetles become serious dangers when they wander into logging camps due to their appetite for decaying wood. Called stag beetles because of their large, antler-like mandibles, they use these appendages to wrestle competing suitors and quickly put down enemy threats. Variant species of these giant beetles exist as well. The two detailed below are the ones most commonly encountered. Bombardier Beetle (CR 2): This giant stag beetle has only 2 Hit Dice and is Medium sized, but can spray acid once per round in a 10-foot cone. Those in the cone must make a DC 11 Fortitude save or take 1d4+2 points of acid damage. The save DC is Constitution-based. Goliath Beetle (CR 8): The immense goliath beetle is a Huge stag beetle with 12 HD and the trample special ability.","ecology":"","habitat_society":""}];
